"""Tests for reply_email_draft, reply_all_email_draft, and forward_email_draft.

These tools must NEVER send mail — they only create drafts via Graph's
draft-creating actions (createReply / createReplyAll / createForward) and
optionally PATCH the body/recipients.
"""

from unittest.mock import call, patch

import pytest


