@patch("src.microsoft_mcp.tools.graph")
def test_reply_email_draft_posts_create_reply(mock_graph):
    from src.microsoft_mcp import tools

    mock_graph.request.return_value = _draft_message("d-reply-1")

    result = tools.reply_email_draft.fn(email_id="msg-1")

    mock_graph.request.assert_called_once_with("POST", "/me/messages/msg-1/createReply")
    assert result["status"] == "draft_created"
    assert result["draft_id"] == "d-reply-1"
    assert result["draft"]["is_draft"] is True


@patch("src.microsoft_mcp.tools.graph")
def test_reply_email_draft_patches_body_when_provided(mock_graph):
    from src.microsoft_mcp import tools

    body_text = "<p>Thanks!</p>"
    mock_graph.request.side_effect = [
        _draft_message("d-reply-2"),
        _draft_message("d-reply-2", body={"contentType": "HTML", "content": body_text}),
    ]

    result = tools.reply_email_draft.fn(email_id="msg-2", body=body_text)

    assert mock_graph.request.call_args_list == [
        call("POST", "/me/messages/msg-2/createReply"),
        call(
            "PATCH",
            "/me/messages/d-reply-2",
            json={"body": {"contentType": "HTML", "content": body_text}},
        ),
    ]
    assert result["draft_id"] == "d-reply-2"


