@patch("src.microsoft_mcp.tools.graph")
def test_forward_email_draft_posts_create_forward_and_patches(mock_graph):
    from src.microsoft_mcp import tools

    comment = "<p>FYI</p>"
    patched = _draft_message(
        "d-fwd-1",
        toRecipients=[{"emailAddress": {"address": "carol@example.com"}}],
        body={"contentType": "HTML", "content": comment},
    )
    mock_graph.request.side_effect = [
        _draft_message("d-fwd-1"),
        patched,
    ]

    result = tools.forward_email_draft.fn(
        email_id="msg-20",
        to=["carol@example.com"],
        comment=comment,
    )

    expected_patch_payload = {
        "toRecipients": [{"emailAddress": {"address": "carol@example.com"}}],
        "body": {"contentType": "HTML", "content": comment},
    }
    assert mock_graph.request.call_args_list == [
        call("POST", "/me/messages/msg-20/createForward"),
        call("PATCH", "/me/messages/d-fwd-1", json=expected_patch_payload),
    ]
    assert result["status"] == "draft_created"
    assert result["draft_id"] == "d-fwd-1"
    assert result["draft"]["is_draft"] is True


